import{z as c,x as p,o,c as B,q as E,j as n,D as t,d as l,s as r,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"LSM 与 compaction","description":"","frontmatter":{"title":"LSM 与 compaction","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lsm-compaction.md","filePath":"cs/lsm-compaction.md","lastUpdated":1791413859000}'),m={name:"cs/lsm-compaction.md"};function A(d,a,S,T,D,C){const i=p("Mermaid");return o(),B("div",null,[a[2]||(a[2]=E('<h1 id="lsm-与-compaction" tabindex="-1">LSM 与 compaction <a class="header-anchor" href="#lsm-与-compaction" aria-label="Permalink to &quot;LSM 与 compaction&quot;">​</a></h1><div class="epigraph"><p>先写内存表再刷成不可变文件；compaction 把多层文件归并，用顺序写换读时的多层查找。</p><footer>—— 据 O&#39;Neil, Cheng, Gawlick and O&#39;Neil, The Log-Structured Merge-Tree, Acta Informatica 1996；Google Bigtable；RocksDB</footer></div><p><a href="/cs/art-index-db">上一课</a>给主存有序树。本课不升级 Node48。缺口是写多读少或写吞吐优先：B+ 原地更新造成随机写与页分裂。日志结构归并树（LSM）把写入变成追加：memtable 满则 freeze 成 SSTable（有序文件），后台 compaction 归并重叠键。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>随机写 SSD 也有放大与写寿命。LSM：插入/更新/删除（墓碑）进 memtable（可用跳表或 ART）；刷盘后文件不可变，简化并发（写不改旧文件）。读必须查 memtable + 各层文件，直到找到最新版本。缺口是 <strong>compaction 策略</strong>决定写放大、读放大、空间放大——下一课读放大与布隆，再下一课 leveled vs tiered。</p><p><span class="marginnote">直觉类比：LSM 写像往流水账末尾不停追加新条目，从不涂改旧账；compaction 是定期把几本账誊清成一本——同名条目只留最新一笔，「销户」标记（墓碑）要留到确认所有旧账里都没有同名条目为止。</span></p><p>崩溃：WAL 保护尚未刷盘的 memtable，与主干 WAL 同构，粒度是应用日志。检查点即「哪些文件是当前版本」。</p><p><span class="marginnote">O&#39;Neil et al. 1996 LSM。Bigtable / LevelDB / RocksDB 是工程谱系。本课机制，RocksDB 产品课在数据模型族再讲。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Level-0：新刷的文件可重叠。更高层：compaction 挑选重叠文件归并输出。墓碑要保留到能证明更下层无旧值才丢。快照/MVCC：compaction 不能丢掉仍被快照看见的版本——与后课 MVCC GC 接口。</p><p>节流：compaction 跟不上则写停顿（write stall）。这是 LSM 的运维不变式，不是偶发。</p><p><span class="marginnote">为什么重要：墓碑如果丢早了会「诈尸」——更下层文件里还躺着旧值，读路径找上来，刚删掉的数据又出现了；快照同理，compaction 不尊重 MVCC 就会让长事务读到凭空消失的版本。墓碑与版本的丢弃条件是正确性问题，不是调优项。</span></p>',12)),(o(),n(s,null,{default:t(()=>[r(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E5%86%99%22%5D%20--%3E%20MT%5B%22memtable%22%5D%0A%20%20MT%20--%3E%20SST%5B%22%E5%88%B7%E6%88%90%20SSTable%22%5D%0A%20%20SST%20--%3E%20CMP%5B%22compaction%20%E5%BD%92%E5%B9%B6%22%5D%0A%20%20R%5B%22%E8%AF%BB%22%5D%20--%3E%20MT%0A%20%20R%20--%3E%20SST%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[l("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"顺序写带宽高，代价是读走多文件、写同一键多次（每层一次）。B+ 读放大低、写随机。选择是工作负载，不是谁淘汰谁。延迟物化、列存可叠在 SST 内部格式上（后课 Parquet 是分析侧亲戚）。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"数字实例：leveled compaction 里一个键每下移一层就被重写一次，层大小比 \\(10:1\\) 时写放大常在 10–30 倍——业务写 1 GB，磁盘实际落 10–30 GB。这是用写带宽与 SSD 寿命，换「读时少翻几个文件」的确定性。")],-1)),(o(),n(s,null,{default:t(()=>[r(i,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20PICK%5B%22%E5%9C%A8%20L(i)%20%E9%80%89%E4%B8%80%E4%B8%AA%E6%96%87%E4%BB%B6%22%5D%20--%3E%20FIND%5B%22%E6%89%BE%20L(i%2B1)%20%E9%94%AE%E5%8C%BA%E9%97%B4%E9%87%8D%E5%8F%A0%E7%9A%84%E5%85%A8%E9%83%A8%E6%96%87%E4%BB%B6%22%5D%0A%20%20FIND%20--%3E%20MERGE%5B%22%E5%A4%9A%E8%B7%AF%E5%BD%92%E5%B9%B6%3A%20%E6%96%B0%E7%89%88%E6%9C%AC%E7%9B%96%E6%97%A7%E7%89%88%E6%9C%AC%22%5D%0A%20%20MERGE%20--%3E%20TOMB%7B%22%E5%A2%93%E7%A2%91%E5%B7%B2%E5%9C%A8%E6%9C%80%E5%BA%95%E5%B1%82%3F%22%7D%0A%20%20TOMB%20--%3E%7C%22%E5%90%A6%22%7C%20KEEP%5B%22%E5%A2%93%E7%A2%91%E7%85%A7%E6%8A%84%E8%BF%9B%E8%BE%93%E5%87%BA%22%5D%0A%20%20TOMB%20--%3E%7C%22%E6%98%AF%22%7C%20DROP%5B%22%E4%B8%A2%E5%BC%83%E5%A2%93%E7%A2%91%22%5D%0A%20%20KEEP%20--%3E%20OUT%5B%22%E5%86%99%E5%87%BA%E6%96%B0%20SST%20%E6%96%87%E4%BB%B6%E5%88%B0%20L(i%2B1)%22%5D%0A%20%20DROP%20--%3E%20OUT%0A%20%20OUT%20--%3E%20DEL%5B%22%E5%88%A0%E9%99%A4%E5%85%A8%E9%83%A8%E8%BE%93%E5%85%A5%E6%96%87%E4%BB%B6%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=E('<p>并行：多 compaction 工人，注意与缓冲池争磁盘。pin-latch 模型变成文件+块缓存。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不量化布隆如何砍文件。也不把 leveled/tiered 的放大公式写完。全文倒排也可 LSM，后课。</p><p>后课默认：写走 memtable+SST+compaction。读放大与布隆：用过滤器避免打开无键文件。</p><p>不可变文件让崩溃恢复变成「丢掉未刷 memtable、重放 WAL」，结构修改比 B+ SMO 少。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LSM 用顺序刷盘与归并代替原地更新。</li><li>compaction 是持续税；跟不上则写停顿。</li><li>读放大与布隆下一课。</li><li>出处：O&#39;Neil et al. 1996；Bigtable；RocksDB 设计。</li></ul>',7))])}const u=c(m,[["render",A]]);export{b as __pageData,u as default};
